#!/usr/bin/env python3
"""Generates pages/src/about.bi.html (bilingual source; tools/build-routes.py splits it into pages/about.html + pages/vi/about.html. The Little Prince section was added by hand in the output, re-add it if you regenerate) (story, journey, numbers, life library). Hobby tiles are inline SVG
illustrations; replace one with a real photo by adding <img> in data/about.json later."""
import os
root=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
J='#116b54';T='#b55239';INK='#142824';SA='#e8d9b4';PA='#f6f4ed'
def tile(slug,bg,art,en,vi,cls=''):
    return (f'<figure class="life-tile {cls}" style="--bg:{bg}"><svg viewBox="0 0 240 280" aria-hidden="true">{art}</svg>'
            f'<figcaption data-en="{en}" data-vi="{vi}">{en}</figcaption></figure>')
star=lambda x,y,r=2,c='#fff':f'<circle cx="{x}" cy="{y}" r="{r}" fill="{c}"/>'
art={}
art['book']=f'<rect x="50" y="170" width="140" height="22" rx="3" fill="{J}"/><rect x="60" y="148" width="124" height="22" rx="3" fill="{T}"/><rect x="46" y="126" width="132" height="22" rx="3" fill="{INK}"/><path d="M120 110 C100 86 70 84 52 92 V122 C72 114 100 116 120 130 C140 116 168 114 188 122 V92 C170 84 140 86 120 110Z" fill="#fff" stroke="{INK}" stroke-width="3"/><path d="M120 110V130" stroke="{INK}" stroke-width="3"/>'
art['paint']=f'<path d="M120 60 C60 60 36 108 54 150 C66 178 100 168 104 190 C110 220 160 222 184 188 C214 146 188 60 120 60Z" fill="#fff" stroke="{INK}" stroke-width="3"/>'+''.join(f'<circle cx="{x}" cy="{y}" r="11" fill="{c}"/>' for x,y,c in [(92,100,T),(124,88,'#e8b84a'),(156,104,J),(84,132,'#3a6ea5'),(150,142,'#8a4f9e')])+f'<circle cx="118" cy="176" r="12" fill="{PA}" stroke="{INK}" stroke-width="3"/><path d="M168 222 L214 126" stroke="{INK}" stroke-width="7" stroke-linecap="round"/><path d="M214 126 q8-22 18-16 q-2 16-18 16Z" fill="{T}"/>'
art['animal']=f'<path d="M62 78 L82 130 L130 112 L178 130 L198 78 L160 100 H100Z" fill="#e89a5a"/><ellipse cx="130" cy="170" rx="68" ry="58" fill="#f0a766"/><path d="M96 126 L100 100 L116 118Z M164 126 L160 100 L144 118Z" fill="#f0a766"/><circle cx="106" cy="160" r="8" fill="{INK}"/><circle cx="154" cy="160" r="8" fill="{INK}"/><circle cx="108" cy="157" r="2.6" fill="#fff"/><circle cx="156" cy="157" r="2.6" fill="#fff"/><path d="M122 182 h16 l-8 9z" fill="{T}"/><path d="M130 191 q-12 12-26 6 M130 191 q12 12 26 6" stroke="{INK}" stroke-width="3" fill="none" stroke-linecap="round"/><path d="M84 184 h-32 M86 194 l-30 10 M176 184 h32 M174 194 l30 10" stroke="{INK}" stroke-width="2.4" stroke-linecap="round"/><ellipse cx="130" cy="150" rx="18" ry="6" fill="#fff" opacity=".35"/>'
art['basket']=f'<circle cx="120" cy="140" r="70" fill="{T}"/><path d="M50 140 H190 M120 70 V210 M72 92 Q104 140 72 188 M168 92 Q136 140 168 188" stroke="{INK}" stroke-width="4" fill="none"/><ellipse cx="120" cy="244" rx="52" ry="8" fill="#17382c" opacity=".14"/>'
art['bad']=f'<g transform="rotate(-35 120 150)"><ellipse cx="120" cy="106" rx="38" ry="52" fill="none" stroke="{INK}" stroke-width="6"/><path d="M96 80 H144 M92 100 H148 M92 120 H148 M98 140 H142 M104 62 V150 M120 56 V158 M136 62 V150" stroke="{J}" stroke-width="1.8" opacity=".7"/><rect x="115" y="158" width="10" height="70" rx="5" fill="{INK}"/><rect x="113" y="196" width="14" height="30" rx="5" fill="{T}"/></g><g transform="translate(176 72) rotate(25)"><path d="M0 0 L-16 -34 H16Z" fill="#fff" stroke="{INK}" stroke-width="2.5"/><path d="M-9 -20 H9 M-4 -34 V-4 M4 -34 V-4" stroke="{INK}" stroke-width="1.6"/><circle cx="0" cy="4" r="9" fill="{T}"/></g>'
art['photo']=f'<rect x="38" y="96" width="164" height="112" rx="14" fill="{INK}"/><rect x="82" y="80" width="46" height="22" rx="6" fill="{INK}"/><circle cx="120" cy="152" r="40" fill="#fff"/><circle cx="120" cy="152" r="30" fill="{J}"/><circle cx="120" cy="152" r="14" fill="{INK}"/><circle cx="110" cy="142" r="5" fill="#fff" opacity=".7"/><circle cx="178" cy="116" r="6" fill="{T}"/><rect x="50" y="106" width="22" height="8" rx="3" fill="#fff" opacity=".6"/>'
art['zen']=f'<circle cx="120" cy="140" r="86" fill="#fff" opacity=".5"/><circle cx="120" cy="140" r="62" fill="#fff" opacity=".5"/><circle cx="120" cy="86" r="20" fill="#f0c9a8"/><path d="M82 192 Q120 140 158 192 Q120 214 82 192Z" fill="{J}"/><path d="M96 150 Q120 130 144 150 L158 192 Q120 170 82 192Z" fill="{J}"/><path d="M60 206 Q120 232 180 206 Q150 190 120 194 Q90 190 60 206Z" fill="{T}"/><path d="M104 112 Q120 106 136 112" stroke="{INK}" stroke-width="3" fill="none" stroke-linecap="round" transform="translate(0 -22)"/>'
art['cosmos']=f'<circle cx="120" cy="140" r="52" fill="{T}"/><path d="M82 128 Q120 112 158 130 M76 152 Q120 140 164 154" stroke="#e3a08c" stroke-width="7" fill="none" stroke-linecap="round"/><ellipse cx="120" cy="140" rx="104" ry="24" transform="rotate(-18 120 140)" fill="none" stroke="{SA}" stroke-width="7"/><path d="M26 166 A104 24 -18 0 0 214 114" fill="none" stroke="{INK}" stroke-width="0"/>'+''.join(star(x,y,r) for x,y,r in [(40,50,2.4),(190,40,3),(210,100,2),(30,220,2.4),(200,230,3),(88,36,2),(150,250,2)])+f'<path d="M186 72 l3 9 9 3 -9 3 -3 9 -3-9 -9-3 9-3z" fill="{SA}"/>'
art['spirit']=f'<circle cx="120" cy="96" r="34" fill="{SA}"/><circle cx="132" cy="90" r="30" fill="#fff" opacity=".0"/><path d="M120 218 C84 218 60 190 66 160 C84 170 100 176 120 196 C140 176 156 170 174 160 C180 190 156 218 120 218Z" fill="{T}"/><path d="M120 206 C96 176 96 140 120 118 C144 140 144 176 120 206Z" fill="#e3a08c"/><path d="M64 178 C40 168 38 140 52 126 C66 138 82 156 92 184Z" fill="{J}"/><path d="M176 178 C200 168 202 140 188 126 C174 138 158 156 148 184Z" fill="{J}"/>'+''.join(star(x,y,r,SA) for x,y,r in [(36,70,2.6),(206,60,2.6),(60,40,2),(186,128,2)])
art['climb']=f'<path d="M0 230 L70 110 L110 170 L150 80 L240 230Z" fill="{INK}" opacity=".88"/><path d="M150 80 L124 124 L140 118 L150 134 L162 116 L180 126Z" fill="#fff"/><path d="M70 110 L52 142 L66 138 L76 150 L88 134Z" fill="#fff"/><path d="M0 230 L60 170 L120 230Z" fill="{J}"/><path d="M150 80 V50" stroke="{INK}" stroke-width="4"/><path d="M150 52 H182 L172 62 L182 72 H150Z" fill="{T}"/>'+star(40,56,3,'#fff')+star(200,40,2.4,'#fff')
tiles=[
 tile('book','#eee6d2',art['book'],'Reading','Đọc sách'),
 tile('paint','#f0ddd5',art['paint'],'Painting','Vẽ tranh'),
 tile('animal','#f1e9cf',art['animal'],'Animals','Động vật'),
 tile('basket','#e7e0cc',art['basket'],'Basketball','Bóng rổ'),
 tile('bad','#dfe6ed',art['bad'],'Badminton','Cầu lông'),
 tile('photo','#dceae1',art['photo'],'Photography','Chụp hình'),
 tile('zen','#f0e6d9',art['zen'],'Meditation','Ngồi thiền'),
 tile('cosmos','#1d2f3d',art['cosmos'],'The universe','Vũ trụ','dark'),
 tile('spirit','#efe0e2',art['spirit'],'Spirituality','Tâm linh'),
 tile('climb','#cfe0d6',art['climb'],'Climbing','Leo núi'),
 '<figure class="life-tile more-tile" style="--bg:#f6f4ed"><div class="more-in"><em>&amp;</em><span data-en="and a long list still growing…" data-vi="và danh sách vẫn đang dài thêm…">and a long list still growing…</span></div></figure>']
def tl(year,en_t,vi_t,en_d,vi_d):
    return f'<li><b>{year}</b><div><h3 data-en="{en_t}" data-vi="{vi_t}">{en_t}</h3><p data-en="{en_d}" data-vi="{vi_d}">{en_d}</p></div></li>'
tls=''.join([
 tl('Childhood','The kid with a hundred thousand “whys”','Cô bé mười vạn câu hỏi vì sao','Curious from the very start, reading everything that explained how the world works, and never satisfied with a single answer.','Tò mò từ bé, đọc mười vạn câu hỏi vì sao, cái gì cũng muốn biết vì sao lại như vậy và chưa bao giờ hài lòng với một câu trả lời.'),
 tl('2021','Content marketing at Nhang Thiện JSC','Content Marketing tại Nhang Thiện','Learning to connect customer insight, brand and everyday words people can actually feel.','Học cách nối thấu hiểu khách hàng, thương hiệu và những câu chữ mà người đọc thật sự cảm được.'),
 tl('2022','UX Content Lead at JAMstack Vietnam','UX Content Lead tại JAMstack Vietnam','Content systems and digital experiences for 60+ website, app and software projects in healthcare, e-commerce, insurance and more.','Dựng hệ thống nội dung và trải nghiệm số cho hơn 60 dự án website, app, phần mềm: y tế, thương mại điện tử, bảo hiểm và nhiều ngành khác.'),
 tl('2024','Product Owner at Easy AI','Product Owner tại Easy AI','From discovery to go-live for AI assistants, live chat and AI call center, across retail, healthcare, electronics and insurance.','Từ khám phá bài toán đến go-live cho trợ lý AI, live chat, tổng đài AI trong bán lẻ, y tế, điện máy, bảo hiểm.'),
 tl('Now','Still exploring, fully','Vẫn đang khám phá, trọn vẹn','Work is one chapter I give everything to, next to many others I would never give up.','Công việc là một chương mình dốc hết sức, bên cạnh rất nhiều chương khác mình không muốn bỏ.')])
nums=''.join(f'<div><em>{n}</em><span data-en="{e}" data-vi="{v}">{e}</span></div>' for n,e,v in [('5+','years across product, UX and AI','năm làm sản phẩm, UX và AI'),('60+','website, app and software projects','dự án website, app, phần mềm'),('11x','ROI for MWG in 8 weeks','ROI cho MWG trong 8 tuần'),('10B','tokens processed by the product','token được xử lý bởi sản phẩm')])
values=''.join(f'<li><b>{n}</b><h3 data-en="{e}" data-vi="{v}">{e}</h3><p data-en="{ed}" data-vi="{vd}">{ed}</p></li>' for n,e,v,ed,vd in [
 ('01','Kind, and easy to be with','Thiện lành, chan hoà','Warm with everyone, in every room.','Chan hoà với mọi người, ở bất cứ không gian nào.'),
 ('02','All in, and enjoy every moment','Hết mình, tận hưởng từng khoảnh khắc','When I commit, I give everything, and I still savour the ride.','Đã làm thì làm hết mình, và vẫn tận hưởng từng khoảnh khắc trên đường đi.'),
 ('03','Work is a hobby, not everything','Công việc như một sở thích, không là tất cả','A big part of life, never the whole of it.','Một phần lớn của cuộc sống, nhưng không bao giờ là toàn bộ.')])
html=f'''<section class="about-hero">
<label data-en="ABOUT" data-vi="VỀ MÌNH">ABOUT</label>
<h1 data-en="Someone of <em>many trades,</em> living on Earth <em>fully.</em>" data-vi="Người của <em>muôn nghề,</em> sống trên Trái Đất <em>trọn vẹn.</em>">Someone of <em>many trades,</em> living on Earth <em>fully.</em></h1>
<p data-en="Jade, Bích Ngọc: curious since childhood, now an AI Product Owner who still wants to experience life as fully and vividly as possible." data-vi="Mong muốn sống một cuộc đời sống động và làm những điều theo con tim mách bảo.">Jade, Bích Ngọc: curious since childhood, now an AI Product Owner who still wants to experience life as fully and vividly as possible.</p>
</section>
<section class="about-story">
<div class="story-side"><label data-en="MY STORY" data-vi="CÂU CHUYỆN">MY STORY</label></div>
<div class="story-text">
<p class="lead" data-en="As a kid I read a hundred thousand “whys” and I never really stopped asking." data-vi="Từ bé mình đã đọc mười vạn câu hỏi vì sao, và đến giờ vẫn chưa thôi hỏi.">As a kid I read a hundred thousand “whys” and I never really stopped asking.</p>
<p data-en="Growing up, I liked everything: books, drawing, animals, sport, cameras, the stars. I could be a person of many trades, yet what I want most is simple: to live this life on Earth as fully and vividly as I can." data-vi="Lớn lên, mình thích đủ thứ: sách, vẽ, động vật, thể thao, máy ảnh, các vì sao. Có thể là người của muôn nghề, nhưng điều mình muốn nhất vẫn giản dị: sống trọn vẹn và sống động nhất cuộc đời trên Trái Đất này.">Growing up, I liked everything: books, drawing, animals, sport, cameras, the stars. I could be a person of many trades, yet what I want most is simple: to live this life on Earth as fully and vividly as I can.</p>
<p data-en="I try to stay kind and easy with everyone, and to give my all and savour every moment. Work is one part of life, something I treat like a hobby but not the whole of it. And when I do it, I do it wholeheartedly." data-vi="Mình cố gắng thiện lành, chan hoà với mọi người, hướng đến lý tưởng làm hết mình và tận hưởng mọi khoảnh khắc. Công việc là một phần, xem như một sở thích nhưng không là tất cả. Còn khi đã làm thì mình làm hết mình.">I try to stay kind and easy with everyone, and to give my all and savour every moment. Work is one part of life, something I treat like a hobby but not the whole of it. And when I do it, I do it wholeheartedly.</p>
<p class="sign-line" data-en="All of it, gathered together, is Jade. Is Bích Ngọc." data-vi="Hội tụ lại, là Jade. Là Bích Ngọc.">All of it, gathered together, is Jade. Is Bích Ngọc.</p>
</div></section>
<section class="about-journey">
<div class="journey-head"><label data-en="THE JOURNEY" data-vi="HÀNH TRÌNH">THE JOURNEY</label><h2 data-en="From curious kid to <em>building AI products.</em>" data-vi="Từ cô bé tò mò đến <em>làm sản phẩm AI.</em>">From curious kid to <em>building AI products.</em></h2></div>
<ol class="journey">{tls}</ol></section>
<section class="about-life">
<div class="life-head"><label data-en="THE LIFE LIBRARY" data-vi="THƯ VIỆN CUỘC SỐNG">THE LIFE LIBRARY</label><h2 data-en="Many corners of <em>one life.</em>" data-vi="Nhiều góc nhỏ của <em>một cuộc đời.</em>">Many corners of <em>one life.</em></h2><p data-en="The things I love outside of work, the ones that keep life wide." data-vi="Những điều mình yêu ngoài công việc, những điều giữ cho cuộc sống luôn rộng mở.">The things I love outside of work, the ones that keep life wide.</p></div>
<div class="life-grid">{''.join(tiles)}</div></section>
<section class="about-values"><label data-en="HOW I LIVE & WORK" data-vi="CÁCH MÌNH SỐNG VÀ LÀM VIỆC">HOW I LIVE & WORK</label><ul>{values}</ul></section>
<section class="close"><label data-en="LET'S TALK" data-vi="TRÒ CHUYỆN">LET'S TALK</label><h2 data-en="Curious about something? <em>Let's talk.</em>" data-vi="Tò mò điều gì đó? <em>Mình trò chuyện nhé.</em>">Curious about something? <em>Let's talk.</em></h2><a href="/contact" data-en="Get in touch ↗︎" data-vi="Liên hệ ↗︎">Get in touch ↗︎</a></section>
'''
open(os.path.join(root,'pages','src','about.bi.html'),'w',encoding='utf8').write(html.replace('HOW I LIVE & WORK','HOW I LIVE &amp; WORK'))
